var combinationSum = function(candidates, target) {
    const res = [];
    const path = [];
    function backtrack(remain, start) {
        if (remain === 0) {
            res.push([...path]);
            return;
        }
        if (remain < 0) return;
        for (let i = start; i < candidates.length; i++) {
            path.push(candidates[i]);
            backtrack(remain - candidates[i], i);
            path.pop();
        }
    }
    backtrack(target, 0);
    return res;
};
